changeSet.sql:
CREATE TABLE ${ARENA_DB_SCHEMA}.facility_qr_challenge (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 academy_id BIGINT NOT NULL REFERENCES ${ARENA_DB_SCHEMA}.customer(id), facility_id BIGINT NOT NULL,
 token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, used_at TIMESTAMP WITH TIME ZONE,
 FOREIGN KEY(facility_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_play_area(id,academy_id),
 UNIQUE(id,academy_id,facility_id)
);
CREATE INDEX facility_qr_expiry ON ${ARENA_DB_SCHEMA}.facility_qr_challenge(expires_at);
CREATE TABLE ${ARENA_DB_SCHEMA}.facility_customer_checkin (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 academy_id BIGINT NOT NULL, facility_id BIGINT NOT NULL, challenge_id BIGINT NOT NULL UNIQUE,
 customer_name VARCHAR(100), mobile VARCHAR(16),
 status VARCHAR(16) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','CANCELLED','EXPIRED')),
 created_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
 confirmed_at TIMESTAMP WITH TIME ZONE, confirmed_by VARCHAR(100), session_id BIGINT UNIQUE,
 FOREIGN KEY(challenge_id,academy_id,facility_id) REFERENCES ${ARENA_DB_SCHEMA}.facility_qr_challenge(id,academy_id,facility_id),
 FOREIGN KEY(session_id,academy_id) REFERENCES ${ARENA_DB_SCHEMA}.academy_running_session(id,academy_id),
 CHECK((status='CONFIRMED' AND session_id IS NOT NULL AND confirmed_at IS NOT NULL) OR (status<>'CONFIRMED' AND session_id IS NULL)),
 CHECK(mobile IS NULL OR mobile ~ '^\+[1-9][0-9]{7,14}$')
);
CREATE INDEX facility_checkin_pending ON ${ARENA_DB_SCHEMA}.facility_customer_checkin(academy_id,status,expires_at,created_at);
CREATE INDEX facility_checkin_retention ON ${ARENA_DB_SCHEMA}.facility_customer_checkin(status,confirmed_at,expires_at);
